_person_consent_decision_subject_da151d9ec8dd4596" = given."breg_f_person_consent_decision_subject_da151d9ec8dd4596" AND revoked."breg_f_person_consent_decision_recipient_01eee14e543f0ded" = given."breg_f_person_consent_decision_recipient_01eee14e543f0ded" AND revoked."breg_f_person_consent_decision_purpose_095b26b2691d4462" = given."breg_f_person_consent_decision_purpose_095b26b2691d4462" AND revoked."breg_f_person_consent_decision_scope_252e5c1148cd3415" = given."breg_f_person_consent_decision_scope_252e5c1148cd3415" AND revoked."breg_f_person_consent_decision_decision_cec0416a3d33b849" IN (''invalidated'', ''refused'', ''withdrawn'') AND revoked.record_lifecycle = ''active'' AND LEAST(revoked."breg_f_person_consent_decision_effective_at_8a2677c350b7f6e1", revoked.created_at) >= LEAST(given."breg_f_person_consent_decision_effective_at_8a2677c350b7f6e1", given.created_at)); PERFORM set_config(''registry.consent_probe'', COALESCE(prior_marker, ''''), true); RETURN; EXCEPTION WHEN OTHERS THEN RAISE; END';
